import{_ as l,a0 as d,w as o,s as p,I as s,x as e,a1 as n,A as a,ao as g}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在 Linux 中使用 find | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 find | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 find | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 find | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180427 How to use FIND in Linux","title":"如何在 Linux 中使用 find","tag":"201805","desc":""},"relativePath":"201805/20180427 How to use FIND in Linux.md","filePath":"[post].md"}'),r={name:"201805/20180427 How to use FIND in Linux.md"};function u(h,i,k,c,f,b){const t=d("Link");return o(),p("div",null,[i[20]||(i[20]=s("h1",{id:"如何在-linux-中使用-find",tabindex:"-1"},[e("如何在 Linux 中使用 find "),s("a",{class:"header-anchor",href:"#如何在-linux-中使用-find","aria-label":"Permalink to “如何在 Linux 中使用 find”"},"​")],-1)),i[21]||(i[21]=s("blockquote",null,[s("p",null,[e("使用正确的参数，"),s("code",null,"find"),e(" 命令是在你的系统上找到数据的强大而灵活的方式。")])],-1)),i[22]||(i[22]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/rh_003499_01_linux31x_cc.png?itok=Pvim4U-B",alt:""})],-1)),s("p",null,[i[1]||(i[1]=e("在",-1)),n(t,{href:"https://linux.cn/article-9585-1.html"},{default:a(()=>[...i[0]||(i[0]=[e("最近的一篇文章",-1)])]),_:1}),i[2]||(i[2]=e("中，Lewis Cowles 介绍了 ",-1)),i[3]||(i[3]=s("code",null,"find",-1)),i[4]||(i[4]=e(" 命令。",-1))]),i[23]||(i[23]=g('<p><code>find</code> 是日常工具箱中功能更强大、更灵活的命令行工具之一，因此值得花费更多的时间。</p><p>最简单的，<code>find</code> 跟上路径寻找一些东西。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /</span></span></code></pre></div><p>它将找到（并打印出）系统中的每个文件。而且由于一切都是文件，你会得到很多需要整理的输出。这可能不能帮助你找到你要找的东西。你可以改变路径参数来缩小范围，但它不会比使用 <code>ls</code> 命令更有帮助。所以你需要考虑你想要找的东西。</p><p>也许你想在主目录中找到所有的 JPEG 文件。 <code>-name</code> 参数允许你将结果限制为与给定模式匹配的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ -name &#39;*jpg&#39;</span></span></code></pre></div><p>可是等等！如果它们中的一些是大写的扩展名会怎么样？<code>-iname</code> 就像 <code>-name</code>，但是不区分大小写。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ -iname &#39;*jpg&#39;</span></span></code></pre></div><p>很好！但是 8.3 名称方案是如此的老。一些图片可能是 .jpeg 扩展名。幸运的是，我们可以将模式用“或”（表示为 <code>-o</code>）来组合。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ ( -iname &#39;jpeg&#39; -o -iname &#39;jpg&#39; )</span></span></code></pre></div><p>我们正在接近目标。但是如果你有一些以 jpg 结尾的目录呢？ （为什么你要命名一个 <code>bucketofjpg</code> 而不是 <code>pictures</code> 的目录就超出了本文的范围。）我们使用 <code>-type</code> 参数修改我们的命令来查找文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type f</span></span></code></pre></div><p>或者，也许你想找到那些命名奇怪的目录，以便稍后重命名它们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type d</span></span></code></pre></div><p>你最近拍了很多照片，所以让我们把它缩小到上周更改的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ \\( -iname &#39;*jpeg&#39; -o -iname &#39;*jpg&#39; \\) -type f -mtime -7</span></span></code></pre></div><p>你可以根据文件状态更改时间 （<code>ctime</code>）、修改时间 （<code>mtime</code>） 或访问时间 （<code>atime</code>） 来执行时间过滤。 这些是在几天内，所以如果你想要更细粒度的控制，你可以表示为在几分钟内（分别是 <code>cmin</code>、<code>mmin</code> 和 <code>amin</code>）。 除非你确切地知道你想要的时间，否则你可能会在 <code>+</code> （大于）或 <code>-</code> （小于）的后面加上数字。</p><p>但也许你不关心你的照片。也许你的磁盘空间不够用，所以你想在 <code>log</code> 目录下找到所有巨大的（让我们定义为“大于 1GB”）文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /var/log -size +1G</span></span></code></pre></div><p>或者，也许你想在 <code>/data</code> 中找到 bcotton 拥有的所有文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /data -owner bcotton</span></span></code></pre></div><p>你还可以根据权限查找文件。也许你想在你的主目录中找到对所有人可读的文件，以确保你不会过度分享。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find ~ -perm -o=r</span></span></code></pre></div><p>这篇文章只说了 <code>find</code> 能做什么的表面。将测试条件与布尔逻辑相结合可以为你提供难以置信的灵活性，以便准确找到要查找的文件。并且像 <code>-exec</code> 或 <code>-delete</code> 这样的参数，你可以让 <code>find</code> 对它发现的内容采取行动。你有任何最喜欢的 <code>find</code> 表达式么？在评论中分享它们！</p><hr>',25)),s("p",null,[i[6]||(i[6]=e("via: ",-1)),n(t,{href:"https://opensource.com/article/18/4/how-use-find-linux"},{default:a(()=>[...i[5]||(i[5]=[e("https://opensource.com/article/18/4/how-use-find-linux",-1)])]),_:1})]),s("p",null,[i[11]||(i[11]=e("作者：",-1)),n(t,{href:"https://opensource.com/users/bcotton"},{default:a(()=>[...i[7]||(i[7]=[e("Ben Cotton",-1)])]),_:1}),i[12]||(i[12]=e(" 选题：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[8]||(i[8]=[e("lujun9972",-1)])]),_:1}),i[13]||(i[13]=e(" 译者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:a(()=>[...i[9]||(i[9]=[e("geekpi",-1)])]),_:1}),i[14]||(i[14]=e(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[10]||(i[10]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[15]||(i[15]=[e("LCTT",-1)])]),_:1}),i[18]||(i[18]=e(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...i[16]||(i[16]=[e("Linux中国",-1)])]),_:1}),i[19]||(i[19]=e(" 荣誉推出",-1))])])}const y=l(r,[["render",u]]);export{C as __pageData,y as default};
